create table if not exists public.game_control(game_id text primary key,enabled boolean not null default false,message text not null default 'The arena is not open yet.',updated_at timestamptz not null default now());
create table if not exists public.results(id bigint generated by default as identity primary key,submission_id text not null unique,game_id text not null,player_name text not null check(char_length(player_name) between 2 and 40),score integer not null check(score between 0 and 1950),correct integer not null check(correct between 0 and 15),attempted integer not null check(attempted between 0 and 15),total integer not null default 15 check(total=15),skipped integer not null check(skipped between 0 and 15),time_seconds integer not null check(time_seconds between 0 and 180),started_at timestamptz,completed_at timestamptz not null default now(),answers jsonb not null default '[]'::jsonb);
create index if not exists results_game_leaderboard_idx on public.results(game_id,score desc,time_seconds asc,completed_at asc);
alter table public.game_control enable row level security;alter table public.results enable row level security;
insert into public.game_control(game_id,enabled,message) values('ITV-AI-ARENA-NOV2026',false,'The arena is not open yet.') on conflict(game_id) do update set enabled=false,message=excluded.message,updated_at=now();
